    # Recursive alternating bands around the two full-length dividers.
    for r in range(h):
        for c in range(w):
            if r == hr or c == vc:
                continue
            y = r if r < hr else r - hr - 1
            x = c if c < vc else c - vc - 1

            # At each binary scale a row band or column band is painted;
            # the most significant differing band determines the cell.
            decisions = []
            while x or y:
                decisions.append((x & 1, y & 1))
                x >>= 1
                y >>= 1
            fill = False
            for xb, yb in reversed(decisions):
                if xb != yb:
                    fill = bool(xb)
            out[r][c] = 4 if fill else 0
    return out
